return function(ctx,title,message,buttons) local backdrop=Instance.new("TextButton",ctx.Overlay);backdrop.Name="Dialog";backdrop.Size=UDim2.fromScale(1,1);backdrop.BackgroundColor3=ctx.Theme:Get("Overlay");backdrop.BackgroundTransparency=.35;backdrop.Text="";backdrop.ZIndex=800;local f=Instance.new("Frame",backdrop);f.AnchorPoint=Vector2.new(.5,.5);f.Position=UDim2.fromScale(.5,.5);f.Size=UDim2.fromOffset(380,200);f.BackgroundColor3=ctx.Theme:Get("Surface");f.ZIndex=801;Instance.new("UICorner",f).CornerRadius=UDim.new(0,14);local t=Instance.new("TextLabel",f);t.Position=UDim2.fromOffset(18,16);t.Size=UDim2.new(1,-36,0,26);t.BackgroundTransparency=1;t.Text=title or "Dialog";t.TextColor3=ctx.Theme:Get("Text");t.Font=Enum.Font.GothamBold;t.TextSize=17;t.TextXAlignment=Enum.TextXAlignment.Left;local m=Instance.new("TextLabel",f);m.Position=UDim2.fromOffset(18,50);m.Size=UDim2.new(1,-36,0,90);m.BackgroundTransparency=1;m.Text=message or "";m.TextColor3=ctx.Theme:Get("Muted");m.Font=Enum.Font.Gotham;m.TextSize=13;m.TextWrapped=true;m.TextXAlignment=Enum.TextXAlignment.Left;local x=0;for _,btn in ipairs(buttons or {{Text="Close",Callback=function()backdrop:Destroy()end}})do x+=1;local b=Instance.new("TextButton",f);b.Size=UDim2.fromOffset(105,36);b.Position=UDim2.new(1,-18-(x*111),1,-52);b.BackgroundColor3=ctx.Theme:Get("SurfaceAlt");b.TextColor3=ctx.Theme:Get("Text");b.Text=btn.Text or "Action";b.Font=Enum.Font.GothamMedium;b.TextSize=13;Instance.new("UICorner",b).CornerRadius=UDim.new(0,9);ctx.Input:BindPress(b,function()if btn.Callback then btn.Callback()end;backdrop:Destroy()end)end;return Component.new(backdrop,ctx) end
